INSERT INTO lessons (id, module_id, title, description, lesson_type, sort_order)
INSERT INTO lesson_steps (id, lesson_id, title, content, sort_order)
VALUES
  (gen_random_uuid(), 'b0000012-0000-0000-0000-000000000012', 'Идея светофора', 'На светофоре три лампы: красный — «стой», жёлтый — «внимание», зелёный — «иди». Мы сделаем так: несколько секунд горит красный, потом он гаснет и загорается жёлтый, потом зелёный, потом снова красный. И так по кругу. Можно потом добавить кнопку: нажал — переключился на зелёный.', 0),
  (gen_random_uuid(), 'b0000012-0000-0000-0000-000000000012', 'Схема', 'Три светодиода: красный, жёлтый, зелёный. Каждый через резистор 220 Ом к своему пину. Например: красный — GP14, жёлтый — GP15, зелёный — GP16. Минусы всех трёх — в общий GND. Собери по схеме, питание отключай при подключении проводов.', 1),
  (gen_random_uuid(), 'b0000012-0000-0000-0000-000000000012', 'Код', 'red = Pin(14, Pin.OUT); yellow = Pin(15, Pin.OUT); green = Pin(16, Pin.OUT). В цикле while True: включи красный, выключи жёлтый и зелёный, time.sleep(3). Потом выключи красный, включи жёлтый, time.sleep(1). Выключи жёлтый, включи зелёный, time.sleep(3). Выключи зелёный — и снова в начало цикла. Числа 3 и 1 — это секунды; можешь поменять.', 2),
  (gen_random_uuid(), 'b0000012-0000-0000-0000-000000000012', 'Собери и проверь на Pico', 'Загрузи код на Pico. Светофор должен по очереди показывать красный, жёлтый, зелёный. Поэкспериментируй: измени время (например жёлтый 2 секунды) и посмотри, как тебе удобнее.', 3),
  (gen_random_uuid(), 'b0000012-0000-0000-0000-000000000012', 'Повтори в Wokwi', 'В Wokwi добавь три светодиода (красный, жёлтый, зелёный) на пины 14, 15, 16 с резисторами. Вставь тот же код и запусти. Если захочешь, добавь кнопку и сделай так: пока кнопка не нажата — горит красный, нажал — переключился на зелёный на несколько секунд.', 4);
INSERT INTO lesson_materials (id, lesson_id, kind, url_or_path, title)
VALUES
  (gen_random_uuid(), 'b0000012-0000-0000-0000-000000000012', 'mermaid', E'flowchart TB\n  GP14[GP14] --> R[220]\n  R --> RED[Красный LED]\n  RED --> GND[GND]\n  GP15[GP15] --> Y[220]\n  Y --> YEL[Жёлтый LED]\n  YEL --> GND\n  GP16[GP16] --> G[220]\n  G --> GRN[Зелёный LED]\n  GRN --> GND', 'Схема светофора: три лампы'),
  (gen_random_uuid(), 'b0000012-0000-0000-0000-000000000012', 'link', 'https://wokwi.com/projects/new/micropython-pi-pico-w', 'Wokwi: проект светофора');
